    13  typedef struct _err {
    14      VALUE clas;
    15      char  msg[128];
    16  } *Err;
    17
    18  extern VALUE ox_arg_error_class;
    19  extern VALUE ox_parse_error_class;
    20  extern VALUE ox_syntax_error_class;
    21
    22  extern void ox_err_set(Err e, VALUE clas, const char *format, ...);
    23  extern void
    24  _ox_err_set_with_location(Err err, const char *msg, const char *xml, const char *current, const char *file, int line);
    25  extern void ox_err_raise(Err e);
    26
    27  inline static void err_init(Err e) {
    28      e->clas = Qnil;
    29      *e->msg = '\0';
    30  }
    31
    32  inline static int err_has(Err e) {
    33      return (Qnil != e->clas);
    34  }
