    46  void ox_err_set(Err e, VALUE clas, const char *format, ...) {
    47      va_list ap;
    48
    49      va_start(ap, format);
    50      e->clas = clas;
    51      vsnprintf(e->msg, sizeof(e->msg) - 1, format, ap);
    52      va_end(ap);
    53  }
    54
    55  #if __GNUC__ > 4
    56  _Noreturn void
    57  #else
    58  void
    59  #endif
    60  ox_err_raise(Err e) {
    61      rb_raise(e->clas, "%s", e->msg);
    62  }
    63
    64  void _ox_err_set_with_location(Err         err,
    65                                 const char *msg,
    66                                 const char *xml,
    67                                 const char *current,
    68                                 const char *file,
    69                                 int         line) {
    70      int xline = 1;
    71      int col   = 1;
    72
    73      for (; xml < current && '\n' != *current; current--) {
    74          col++;
    75      }
    76      for (; xml < current; current--) {
    77          if ('\n' == *current) {
    78              xline++;
    79          }
    80      }
